{% extends 'tasks/base.html' %}

{% block title %}Task Board - Kanban View{% endblock %}

{% block header %}Task Board - Kanban View{% endblock %}

{% block content %}
<div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1rem;">
    <!-- TO DO Column -->
    <div class="card">
        <h2 style="text-align: center; color: #6c757d;">To Do ({{ todo_tasks.count }})</h2>
        {% for task in todo_tasks %}
            <div class="card status-todo priority-{{ task.get_priority_display|lower }}">
                <h4>{{ task.title }}</h4>
                <p>{{ task.description|truncatewords:10 }}</p>
                <p><strong>Project:</strong> {{ task.project.name }}</p>
                <p><strong>Priority:</strong> {{ task.get_priority_display }}</p>
                {% if task.due_date %}
                    <p><strong>Due:</strong> {{ task.due_date }}</p>
                    {% if task.is_overdue %}
                        <span style="color: #e74c3c; font-weight: bold;">⚠️ OVERDUE</span>
                    {% endif %}
                {% endif %}
            </div>
        {% empty %}
            <div class="card">
                <p style="text-align: center; color: #6c757d;">No tasks to do! </p>
            </div>
        {% endfor %}
    </div>

    <!-- IN PROGRESS Column -->
    <div class="card">
        <h2 style="text-align: center; color: #f39c12;">In Progress ({{ doing_tasks.count }})</h2>
        {% for task in doing_tasks %}
            <div class="card status-doing priority-{{ task.get_priority_display|lower }}">
                <h4>{{ task.title }}</h4>
                <p>{{ task.description|truncatewords:10 }}</p>
                <p><strong>Project:</strong> {{ task.project.name }}</p>
                <p><strong>Priority:</strong> {{ task.get_priority_display }}</p>
                {% if task.due_date %}
                    <p><strong>Due:</strong> {{ task.due_date }}</p>
                    {% if task.is_overdue %}
                        <span style="color: #e74c3c; font-weight: bold;">⚠️ OVERDUE</span>
                    {% endif %}
                {% endif %}
            </div>
        {% empty %}
            <div class="card">
                <p style="text-align: center; color: #6c757d;">Nothing in progress</p>
            </div>
        {% endfor %}
    </div>

    <!-- DONE Column -->
    <div class="card">
        <h2 style="text-align: center; color: #27ae60;">Done ({{ done_tasks.count }})</h2>
        {% for task in done_tasks %}
            <div class="card status-done priority-{{ task.get_priority_display|lower }}">
                <h4>{{ task.title }}</h4>
                <p>{{ task.description|truncatewords:10 }}</p>
                <p><strong>Project:</strong> {{ task.project.name }}</p>
                <p><strong>Priority:</strong> {{ task.get_priority_display }}</p>
                {% if task.due_date %}
                    <p><strong>Due:</strong> {{ task.due_date }}</p>
                {% endif %}
                <span style="color: #27ae60;">✅ Completed</span>
            </div>
        {% empty %}
            <div class="card">
                <p style="text-align: center; color: #6c757d;">No completed tasks yet</p>
            </div>
        {% endfor %}
    </div>
</div>

{% if overdue_tasks %}
<div class="card overdue" style="margin-top: 2rem;">
    <h3 style="color: #e74c3c;">⚠️ Overdue Tasks ({{ overdue_tasks.count }})</h3>
    {% for task in overdue_tasks %}
        <p>• {{ task.title }} ({{ task.project.name }}) - Due: {{ task.due_date }}</p>
    {% endfor %}
</div>
{% endif %}
{% endblock %}

{% extends 'tasks/base.html' %}

{% block title %}{{ priority_name }} Priority Tasks{% endblock %}

{% block header %}{{ priority_name }} Priority Tasks ({{ total_count }}){% endblock %}

{% block content %}
<div class="card">
    <h2>Filter: {{ priority_name }} Priority Tasks</h2>
    <p>Showing all tasks with <strong>{{ priority_name }}</strong> priority level</p>

    <div style="margin: 1rem 0;">
        <a href="{% url 'tasks_by_priority' 3 %}" style="margin-right: 0.5rem; padding: 0.5rem 1rem; background-color: #e74c3c; color: white; text-decoration: none; border-radius: 4px;">High Priority</a>
        <a href="{% url 'tasks_by_priority' 2 %}" style="margin-right: 0.5rem; padding: 0.5rem 1rem; background-color: #f39c12; color: white; text-decoration: none; border-radius: 4px;">Medium Priority</a>
        <a href="{% url 'tasks_by_priority' 1 %}" style="margin-right: 0.5rem; padding: 0.5rem 1rem; background-color: #27ae60; color: white; text-decoration: none; border-radius: 4px;">Low Priority</a>
    </div>
</div>

<div class="card">
    <h3>Tasks ({{ total_count }} found)</h3>
    {% for task in tasks %}
        <div class="card priority-{{ task.get_priority_display|lower }} status-{{ task.get_status_display|lower|cut:' ' }}">
            <div style="display: flex; justify-content: space-between; align-items: start;">
                <div>
                    <h4>{{ task.title }}</h4>
                    <p>{{ task.description }}</p>
                    <p><strong>Project:</strong> {{ task.project.name }}</p>
                </div>
                <div style="text-align: right;">
                    <span class="badge" style="background-color: 
                        {% if task.priority == 3 %}#e74c3c{% elif task.priority == 2 %}#f39c12{% else %}#27ae60{% endif %}; 
                        color: white; padding: 0.25rem 0.5rem; border-radius: 4px; font-size: 0.8rem;">
                        {{ task.get_priority_display }}
                    </span>
                    <br>
                    <span class="badge" style="background-color: 
                        {% if task.status == 1 %}#6c757d{% elif task.status == 2 %}#f39c12{% else %}#27ae60{% endif %}; 
                        color: white; padding: 0.25rem 0.5rem; border-radius: 4px; font-size: 0.8rem; margin-top: 0.25rem;">
                        {{ task.get_status_display }}
                    </span>
                </div>
            </div>
            {% if task.due_date %}
                <p><strong>Due Date:</strong> {{ task.due_date|date:"M d, Y" }}
                {% if task.is_overdue %}
                    <span style="color: #e74c3c; font-weight: bold;">⚠️ OVERDUE</span>
                {% endif %}
                </p>
            {% endif %}
            <p><small>Created: {{ task.created_at|date:"M d, Y" }}</small></p>
        </div>
    {% empty %}
        <div class="card" style="text-align: center; color: #6c757d; padding: 2rem;">
            <h4>No {{ priority_name|lower }} priority tasks found</h4>
            <p>There are currently no tasks with {{ priority_name|lower }} priority in the system.</p>
            <p>Try viewing tasks with different priority levels using the buttons above.</p>
        </div>
    {% endfor %}
</div>
{% endblock %}

from django.shortcuts import render, get_object_or_404 from django.http import HttpResponse, JsonResponse from django.contrib.auth.decorators import login_required from django.utils import timezone from .models import Project, Task, Status, Priority import json
# View 1: HttpResponse view - API-style task count def task_stats(request): """ HttpResponse view that returns task statistics as JSON Shows total tasks, completed tasks, and overdue tasks """ total_tasks = Task.objects.count() completed_tasks = Task.objects.filter(status=Status.DONE).count() overdue_tasks = Task.objects.filter( due_date__lt=timezone.localdate(), status__in=[Status.TODO, Status.DOING] ).count()
stats = { 'total_tasks': total_tasks, 'completed_tasks': completed_tasks, 'overdue_tasks': overdue_tasks, 'completion_rate': f"{(completed_tasks/total_tasks*100):.1f}%" if total_tasks > 0 else "0%" }
return HttpResponse(json.dumps(stats), content_type='application/json')
# View 2: render() view - Main task board def task_board(request): """ Main task board view using render() with template Shows all tasks organized by status columns """ # Get all projects and tasks projects = Project.objects.all()
# Organize tasks by status todo_tasks = Task.objects.filter(status=Status.TODO) doing_tasks = Task.objects.filter(status=Status.DOING) done_tasks = Task.objects.filter(status=Status.DONE)
# Calculate overdue tasks overdue_tasks = Task.objects.filter( due_date__lt=timezone.localdate(), status__in=[Status.TODO, Status.DOING] )
context = { 'projects': projects, 'todo_tasks': todo_tasks, 'doing_tasks': doing_tasks, 'done_tasks': done_tasks, 'overdue_tasks': overdue_tasks, 'current_date': timezone.localdate(), }
return render(request, 'tasks/board.html', context)
# View 3: Project detail view with tasks def project_detail(request, project_id): """ Detail view for a specific project showing all its tasks Uses get_object_or_404 for error handling """ project = get_object_or_404(Project, id=project_id) tasks = project.tasks.all()
# Task counts for this project task_counts = { 'total': tasks.count(), 'todo': tasks.filter(status=Status.TODO).count(), 'doing': tasks.filter(status=Status.DOING).count(), 'done': tasks.filter(status=Status.DONE).count(), }
context = { 'project': project, 'tasks': tasks, 'task_counts': task_counts, }
return render(request, 'tasks/project_detail.html', context)
# View 4: Task list by priority def tasks_by_priority(request, priority_level): """ Filter tasks by priority level Shows how to handle URL parameters and filtering """ try: priority = int(priority_level) if priority not in [Priority.LOW, Priority.MED, Priority.HIGH]: raise ValueError except (ValueError, TypeError): return HttpResponse("Invalid priority level", status=400)
tasks = Task.objects.filter(priority=priority) priority_name = Priority(priority).label
context = { 'tasks': tasks, 'priority_level': priority, 'priority_name': priority_name, 'total_count': tasks.count(), }
return render(request, 'tasks/tasks_by_priority.html', context)
